		protected Opportunity generateNewEntity() {
			Opportunity entity = new Opportunity( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new Money(),   new Date(),  java.math.BigDecimal.ZERO,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  null,  null,  null,  new HashSet<>(),  new HashSet<>(),  new HashSet<>(),  new HashSet<>(),  new HashSet<>(),  new HashSet<>(),  new HashSet<>(),  new HashSet<>(),  OpportunityStage.values()[0],  OpportunityType.values()[0],  ForecastCategory.values()[0] );
			
			return( entity );
		}

